// ============================================================
// NORMALIZACIÓN DE UPLINKS TTN
// Proyecto IoT agrícola
//
// Convierte el JSON completo recibido desde TTN en una
// estructura interna limpia para el resto del sistema.
//
// Actualmente:
//   rs485-lb-01 -> Sensor NPK #1
//   rs485-lb-02 -> Sensor NPK #2
//
// Preparado para incorporar otros tipos de sensores después.
// ============================================================


// ------------------------------------------------------------
// 1. Validar estructura básica del mensaje de TTN
// ------------------------------------------------------------

if (!msg.payload || !msg.payload.end_device_ids) {
    node.warn("Uplink descartado: no contiene end_device_ids");
    return null;
}

if (!msg.payload.uplink_message) {
    node.warn("Uplink descartado: no contiene uplink_message");
    return null;
}

if (!msg.payload.uplink_message.decoded_payload) {
    node.warn("Uplink descartado: no contiene decoded_payload");
    return null;
}


// ------------------------------------------------------------
// 2. Extraer información general del uplink
// ------------------------------------------------------------

const deviceId = msg.payload.end_device_ids.device_id;
const receivedAt = msg.payload.received_at;
const decoded = msg.payload.uplink_message.decoded_payload;


// ------------------------------------------------------------
// 3. Catálogo de dispositivos conocidos
//
// Aquí podremos añadir posteriormente el sensor ambiental
// sin modificar el resto de la arquitectura.
// ------------------------------------------------------------

const devices = {

    "rs485-lb-01": {
        node: "npk-01",
        sensorType: "npk",
        description: "Sensor NPK #1"
    },

    "rs485-lb-02": {
        node: "npk-02",
        sensorType: "npk",
        description: "Sensor NPK #2"
    }

};


// ------------------------------------------------------------
// 4. Verificar que conocemos el dispositivo
// ------------------------------------------------------------

if (!devices[deviceId]) {
    node.warn("Uplink descartado: dispositivo no registrado -> " + deviceId);
    return null;
}

const device = devices[deviceId];


// ------------------------------------------------------------
// 5. Procesar según el tipo de sensor
// ------------------------------------------------------------

let measurements = {};

if (device.sensorType === "npk") {

    // Comprobar que existan las tres variables NPK.
    // Se compara contra undefined porque 0 es una lectura válida.

    if (
        decoded.nitrogen === undefined ||
        decoded.phosphorus === undefined ||
        decoded.potassium === undefined
    ) {
        node.warn("Uplink NPK descartado: faltan variables en " + deviceId);
        return null;
    }

    measurements = {
        nitrogen: Number(decoded.nitrogen),
        phosphorus: Number(decoded.phosphorus),
        potassium: Number(decoded.potassium)
    };
}


// ------------------------------------------------------------
// 6. Construir mensaje normalizado
// ------------------------------------------------------------

msg.payload = {

    device_id: deviceId,

    node: device.node,

    sensor_type: device.sensorType,

    description: device.description,

    timestamp: receivedAt,

    measurements: measurements,

    units: {
        nitrogen: "mg/kg",
        phosphorus: "mg/kg",
        potassium: "mg/kg"
    }

};


// ------------------------------------------------------------
// 7. Entregar mensaje al siguiente nodo
// ------------------------------------------------------------

return msg;

// ============================================================
// PREPARAR DATOS PARA INFLUXDB
// Proyecto IoT agrícola
//
// Entrada esperada:
// {
//   device_id: "rs485-lb-01",
//   node: "npk-01",
//   sensor_type: "npk",
//   timestamp: "...",
//   measurements: {
//      nitrogen: ...,
//      phosphorus: ...,
//      potassium: ...
//   }
// }
//
// Salida para node-red-contrib-influxdb:
// msg.payload = [
//     fields,
//     tags
// ]
// ============================================================

const data = msg.payload;

// 1. Validar que exista la estructura normalizada
if (!data || !data.measurements) {
    node.warn("Dato descartado: no existe measurements");
    return null;
}

// 2. Convertir las mediciones a números
const nitrogen = Number(data.measurements.nitrogen);
const phosphorus = Number(data.measurements.phosphorus);
const potassium = Number(data.measurements.potassium);

// 3. Validar que las mediciones sean numéricas
if (
    !Number.isFinite(nitrogen) ||
    !Number.isFinite(phosphorus) ||
    !Number.isFinite(potassium)
) {
    node.warn("Dato descartado: medición NPK no numérica");
    return null;
}

// 4. Fields de InfluxDB
const fields = {
    nitrogen: nitrogen,
    phosphorus: phosphorus,
    potassium: potassium
};

// 5. Tags de InfluxDB
const tags = {
    device_id: String(data.device_id),
    node: String(data.node),
    sensor_type: String(data.sensor_type)
};

// 6. Usar como timestamp el received_at original de TTN
const timestamp = new Date(data.timestamp);

if (Number.isNaN(timestamp.getTime())) {
    node.warn("Dato descartado: timestamp inválido");
    return null;
}

// El nodo InfluxDB está configurado con precisión en milisegundos
msg.timestamp = timestamp.getTime();

// 7. Formato requerido por influxdb out
msg.payload = [
    fields,
    tags
];

return msg;
